            for dirn,(a,b) in ((-1,-dc) if dr>0 else (1,-dc), (-dr,dc) if dr>0 else (dr,-dc)):
                tr,tc=a,b
                # move away from the segment in direction (dirn_a, dirn_b)
                pass
            r0,c0 = (cells[0] if dr>0 else cells[-1])  # "front" end
            d = (dr, dc) if dr>0 else (-dr, -dc)
            for sgn in (1,-1):
                r_,c_ = cells[(len(cells)-1) if sgn==1 else 0] if dr>0 else (cells[0] if sgn==1 else cells[-1])
